contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        string memory name_,
        string memory tokenURI,
        bool finiteSupply,
        bool transferable,
        uint256 itemsRemaining,
        uint256 itemPrice,
        uint16 dailyAllowance
    ) public {
        bool reverted;
        try c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted != c.isAdmin(address(this)) || (reverted == false && c.isAdmin(address(this))));
        // Strengthened single rule: revert flag equals NOT admin
        assert(reverted == !c.isAdmin(address(this)));
    }
    receive() external payable {}
}

