contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address operator) public {
        require(operator != address(this));
        c.setApprovalForAll(operator, true);
        bool approvedAfter = c.isApprovedForAll(address(this), operator);
        bool selfReverted;
        try c.setApprovalForAll(address(this), true) {
            selfReverted = false;
        } catch {
            selfReverted = true;
        }
        bool selfApproved = c.isApprovedForAll(address(this), address(this));
        assert(approvedAfter && selfReverted && !selfApproved);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string memory itemName, string memory tokenURI, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public {
        require(bytes(tokenURI).length > 0);
        uint256 countBefore = c.uniqueTokensOutstanding();
        c.createGameItem(itemName, tokenURI, true, true, itemsRemaining, itemPrice, dailyAllowance);
        uint256 countAfter = c.uniqueTokensOutstanding();
        string memory returned = c.uri(countAfter - 1);
        assert(countAfter == countBefore + 1 && keccak256(bytes(returned)) == keccak256(bytes(tokenURI)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account, uint256 tokenId, uint256 amount) public {
        // The test contract (msg.sender on every call to c) was never granted
        // burner rights (setAllowedBurningAddresses requires isAdmin), and a
        // freshly deployed c has zero balances anywhere.

        uint256 beforeBalance = c.balanceOf(account, tokenId);

        bool reverted;
        try c.burn(account, tokenId, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.balanceOf(account, tokenId);

        // General rule: an unauthorized caller can never destroy tokens —
        // the burn must revert and the balance must be untouched.
        assert(reverted && beforeBalance == afterBalance && afterBalance == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        string memory name_,
        string memory tokenURI,
        bool finiteSupply,
        bool transferable,
        uint256 itemsRemaining,
        uint256 itemPrice,
        uint16 dailyAllowance
    ) public {
        require(bytes(tokenURI).length > 0);
        require(itemsRemaining > 0);

        uint256 countBefore = c.uniqueTokensOutstanding();
        uint256 newId = countBefore;

        c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);

        uint256 countAfter = c.uniqueTokensOutstanding();
        uint256 supply = c.remainingSupply(newId);
        string memory uri = c.uri(newId);

        assert(
            countAfter == countBefore + 1 &&
            supply == itemsRemaining &&
            keccak256(bytes(uri)) == keccak256(bytes(tokenURI))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        string memory name_,
        string memory tokenURI,
        bool finiteSupply,
        bool transferable,
        uint256 itemsRemaining,
        uint256 itemPrice,
        uint16 dailyAllowance
    ) public {
        require(dailyAllowance > 0);
        require(bytes(tokenURI).length == 0);

        uint256 newId = c.uniqueTokensOutstanding();

        c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);

        uint256 remaining = c.getAllowanceRemaining(address(this), newId);

        assert(remaining == dailyAllowance);
    }

    receive() external payable {}
}
